/* @lc app=leetcode id=3243 lang=kotlin */ class Solution { fun shortestDistanceAfterQueries(n: Int, queries: Array<IntArray>): IntArray = Array(n) { ArrayList<Int>() }.also { g -> (0 until n - 1).forEach { g[it].add(it + 1) } }.let { g -> queries.map { (u, v) -> g[u].add(v).let { BooleanArray(n).also { it[0] = true }.let { seen -> generateSequence(listOf(0)) { f -> f.flatMap { g[it] }.filter { x -> !seen[x] }.distinct().onEach { seen[it] = true }.takeIf { it.isNotEmpty() } }.indexOfFirst { (n - 1) in it } } } }.toIntArray() } }